def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # Locate repeated row patterns at a common vertical displacement. Fill only
    # the missing foreground cells in the less-complete occurrence with 1.
    best = None
    for shift in range(1, h):
        for r in range(h-shift):
            a, b = grid[r], grid[r+shift]
            a_fg = sum(x != bg for x in a)
            b_fg = sum(x != bg for x in b)
            common = sum(x != bg and y != bg and x == y for x, y in zip(a, b))
            if common < 3:
                continue
            score = common * 10 - abs(a_fg-b_fg)
            if best is None or score > best[0]:
                best = (score, r, r+shift, a_fg, b_fg)
    if best:
        _, r, rr, ac, bc = best
        if ac >= bc:
            template, target, tr = grid[r], grid[rr], rr
        else:
            template, target, tr = grid[rr], grid[r], r
        for c in range(w):
            if template[c] != bg and target[c] == bg:
                out[tr][c] = 1
    return out

if __name__ == '__main__':
    g = [[5]*24 for _ in range(29)]
