    g[21] = [5,7,5,5,7,5,5]+[7]*11+[5]*6
    g[22] = [5,7,7,5,7,7,5]+[7]*10+[5]*7
    print(transform(g))
    assert len(transform(g)) == 29 and all(len(row) == 24 for row in transform(g))

