def transform(grid):
    out = [row[:] for row in grid]
    # A shortened horizontal stripe ends before the grid edge; color its tail.
    stripe_color = next((v for row in grid for v in row if v != 0), None)
    if stripe_color is None:
        return out
    for r, row in enumerate(grid):
        k = 0
        while k < len(row) and row[k] == stripe_color:
            k += 1
        if 0 < k < len(row) and all(v == 0 for v in row[k:]):
            out[r][k:] = [1] * (len(row) - k)
            break
    return out

