    # The separator lines partition the picture into rectangular panels.
    # Each output cell records whether its panel contains a marked (non-base) pixel.
    h, w = len(grid), len(grid[0])
    row_bands = []
    start = 0
    for r in range(h):
        if all(v == grid[r][0] and v not in (7,) for v in grid[r]):
            if r > start:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))
    col_bands = [(0, 2), (3, w)] if w >= 5 else [(0, w)]
    return [[1 if any(grid[r][c] != 7 for r in range(a,b) for c in range(x,y)) else 0
             for x,y in col_bands] for a,b in row_bands]

