    h, w = len(grid), len(grid[0])
    # Full solid lines are separators. Use their color to identify row/column
    # bands, then tile the unique non-background panel across the layout.
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    rbounds = [-1] + sep_rows + [h]
    cbounds = [-1] + sep_cols + [w]
    panels = []
    for ri in range(len(rbounds)-1):
        r0, r1 = rbounds[ri]+1, rbounds[ri+1]
        for ci in range(len(cbounds)-1):
            c0, c1 = cbounds[ci]+1, cbounds[ci+1]
            panels.append((r0,r1,c0,c1))
    # Background is the most common color in non-separator cells.
    from collections import Counter
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if r not in sep_rows and c not in sep_cols)
    bg = counts.most_common(1)[0][0]
