def transform(grid):
    """Complete each monochrome fragment into the reference motif shape.

    The largest multi-cell color-4 figure is the reference stencil. Other
    components are partial translated copies; retain their cells and paint the
    missing stencil cells in the fragment's color.
    """
    h, w = len(grid), len(grid[0])
    bg = 1
    from collections import defaultdict
    pts = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                pts[grid[r][c]].append((r,c))
    # Locate reference template as the largest component of color 4.
    cells4 = pts.get(4, [])
    if not cells4:
        return [row[:] for row in grid]
    # Reference is the multi-pixel 4 object; get its tight shape.
    r0=min(r for r,c in cells4); c0=min(c for r,c in cells4)
    shape={(r-r0,c-c0) for r,c in cells4}
    out=[row[:] for row in grid]
    # For each non-reference color component, find translation with maximal
    # overlap between its existing cells and the reference stencil.
    for color, cells in pts.items():
        if color == 4:
            continue
        # 8-connected components
        unseen=set(cells)
        comps=[]
        while unseen:
            seed=unseen.pop(); comp={seed}; stack=[seed]
            while stack:
                r,c=stack.pop()
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        q=(r+dr,c+dc)
                        if q in unseen:
                            unseen.remove(q); comp.add(q); stack.append(q)
            comps.append(comp)
        for comp in comps:
            best=None
            for tr in range(h):
                for tc in range(w):
                    overlap=sum((r-tr,c-tc) in shape for r,c in comp)
                    if overlap and (best is None or overlap>best[0]):
                        best=(overlap,tr,tc)
            if best:
                _,tr,tc=best
                for dr,dc in shape:
                    rr,cc=tr+dr,tc+dc
                    if 0<=rr<h and 0<=cc<w and out[rr][cc] in (bg,color):
                        out[rr][cc]=color
    return out

