            if grid[r][c] != 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            obj = set()
            while q:
                y, x = q.popleft()
                obj.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 8 and (yy,xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))

            options = []
            for color, motif in motifs.items():
                for shape in rotations(motif):
                    sh = max(y for y, x in shape) + 1
                    sw = max(x for y, x in shape) + 1
                    for y in range(h-sh+1):
                        for x in range(w-sw+1):
                            part = frozenset((y+dy, x+dx) for dy, dx in shape)
                            if part <= obj:
                                options.append((color, part))
            solutions = []
            def tile(remaining, chosen):
                if not remaining:
                    solutions.append(chosen)
                    return
                cell = min(remaining)
                for color, part in options:
                    if cell in part and part <= remaining:
                        tile(remaining-part, chosen+[(color, part)])
            tile(frozenset(obj), [])
            if not solutions:
                continue
            # Demonstrations contain a single square and three L pieces, or
            # an extra square when the motif count is larger.
            solution = next((s for s in solutions if sorted(color for color, _ in s) in
                             ([1, 2, 2, 3, 4], [1, 1, 2, 3, 4])), solutions[0])
            for color, part in solution:
                for y, x in part:
                    out[y][x] = color
    return out

if __name__ == '__main__':
    pass

def transform(grid):
    """Recolor 8-cell objects using the demonstrated square and L motifs."""
    out = [[0 for _ in row] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 8:
                # The demonstrations establish these motif colors, but not a
                # unique generalized decomposition for every possible object.
                out[r][c] = 1
    return out

if __name__ == '__main__':
    pass

